package com.collabspace.config; import com.collabspace.service.RateLimitService;import jakarta.servlet.http.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import org.springframework.web.servlet.HandlerInterceptor;import java.util.concurrent.ThreadLocalRandom; @Component @RequiredArgsConstructor public class RateLimitInterceptor implements HandlerInterceptor {private final RateLimitService limiter; public boolean preHandle(HttpServletRequest req,HttpServletResponse res,Object handler){String path=req.getRequestURI();if(path.startsWith("/api/auth/")){String ip=req.getRemoteAddr();if(!limiter.allow("auth:"+ip,20,60)){res.setStatus(429);return false;}}return true;}}